{
  "schemaVersion": "0.2",
  "slug": "description-list",
  "name": "DescriptionList",
  "status": "experimental",
  "purpose": "Presents a list of term-description pairs.",
  "scenarios": [
    "Show product metadata",
    "Display key-value pairs",
    "Render a definition list"
  ],
  "props": {
    "items": {
      "type": "string",
      "required": true,
      "description": "Array of {term, description} items."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "List rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "card",
      "page",
      "form"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for layout tables.",
    "Do not use when a regular table is more appropriate."
  ],
  "a11y": {
    "role": "list",
    "keyboard": [],
    "focus": "Not focusable.",
    "labeling": "Terms are labelled by their dt element.",
    "wcag": [
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Single column by default; may be styled into columns externally.",
    "breakpoints": {
      "compact": "Single column.",
      "medium": "Single column.",
      "large": "Single column."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "description-list",
    "states": [
      "default"
    ],
    "intents": [
      "inspect-details"
    ]
  }
}

import './styles.css'

export interface DescriptionListItem {
  term: string
  description: string
}

export interface DescriptionListProps {
  items: DescriptionListItem[]
  className?: string
}

export function DescriptionList({ items, className }: DescriptionListProps) {
  const classes = ['cu-description-list', className].filter(Boolean).join(' ')
  return (
    <dl className={classes} data-ai-role="description-list" data-ai-state="default" data-ai-intent="inspect-details">
      {items.map((item, index) => (
        <div className="cu-description-list__group" key={index}>
          <dt className="cu-description-list__term">{item.term}</dt>
          <dd className="cu-description-list__detail">{item.description}</dd>
        </div>
      ))}
    </dl>
  )
}

.cu-description-list {
  margin: 0;
  color: var(--cu-color-fg-default);
}

.cu-description-list__group {
  display: grid;
  gap: var(--cu-space-1);
  padding-block: var(--cu-space-2);
  border-block-end: 1px solid var(--cu-color-border-default);
}

.cu-description-list__group:last-child {
  border-block-end: 0;
}

.cu-description-list__term {
  font-weight: 600;
}

.cu-description-list__detail {
  margin: 0;
  color: var(--cu-color-fg-default);
}
